Let $\mathcal{E}
\rightarrow W$ be stable at infinity, with reference metric $H_{0}
$, over an asymptotically cylindrical $SU\left( 3\right) -$manifold $W$ as given by the \emph{Calabi-Yau-Tian-Kovalev Theorem 11}; then,
for any $0<T<\infty $, $\mathcal{E}$ admits a $1-$parameter family $\left\{
H_{t}\right\} $ of smooth Hermitian metrics solving $
\index{evolution equation!on Wx[0,T]@on $W\times \left[ 0,T\right] $}$
\begin{equation*}
\left\{ 
\begin{array}{rcl}
H^{-1}
\dfrac{\partial H}{\partial t}
&=&-2\mathbf{i}\hat{F}_{H} \\ 
H\left( 0\right) 
&=&
H_{0}
\end{array}
\right. \quad \text{on}\quad W\times \left[ 0,T\right].
\end{equation*}
Moreover, each $H_{t}$ approaches $H_{0}$ exponentially in all derivatives
over tubular segments $\Sigma_1(S)$ along the noncompact end.
}

Given any $T>0$, the
family of Hermitian metrics $H\left( t\right) $ on $\mathcal{E}\rightarrow W$
defined by $\left( 24\right) $ is the unique, smooth
solution of the evolution equation$
\index{evolution equation!on Wx[0,T]@on $W\times \left[ 0,T\right] $}$
\begin{equation*}
\left\{ 
\begin{array}{c}
H^{-1}
\dfrac{\partial H}{\partial t}=-2\mathbf{i}\hat{F}_{H} \\ 
H\left( 0\right) =H_{0}
\end{array}
\right. \quad \text{on }W\times \left[ 0,T\right] 
\end{equation*}
with $\det H=\det H_0$ and $\sup_{W}\left\vert H\right\vert <\infty $. Furthermore, 
$$
\sup_{W}\vert \hat{F}_{H\left( t\right) }\vert \leq
B=\sup_{W}\vert \hat{F}_{H_{0}}\vert. 
$$
\begin{proof}
Using \emph{Lemma 29} on any compact subset $\Omega_{S_0}:=W_{S_{0}}\times \left[ 0,T\right] $, the $H_{S}$ are $
C^{\infty }-$bounded (uniformly in $S$). By the evolution equation, 
$$
\frac{\partial H_{S}}{\partial t}
\underset{S\rightarrow \infty}{\overset{C^{\infty }\left( \Omega_{S_0} \right)}{\longrightarrow}}
\frac{\partial H}{\partial t}
$$
so $H$ is a solution on $\Omega_{S_0} $ satisfying the
same bounds, and this is independent of the choice of $S_{0}$.
The bound on $\sup_{W}\vert \hat{F}_{H\left( t\right) }\vert $ is immediate from \emph{Corollary 17} and uniqueness is the statement of \emph{Corollary 22}.
\end{proof}
}

Let $\left\{ H\left(
t\right) \mid t\in \left[ 0,T\right] \right\} $ be the solution to the
evolution equation on $\mathcal{E}\rightarrow W$ given by \emph{Proposition 
31}; then
\index{asymptotic decay!of all derivatives of $H(t)$} 
\begin{equation*}
\boxed{H(t) \overset{C^k}{\underset{S\rightarrow\infty}{\longrightarrow}}H_{0},\quad \forall k\in \mathbb{N}.}
\end{equation*}

Let $V$ be an open set of a
Riemannian manifold $X$, $V^{\prime }\Subset\ V$ an interior domain and $Q\rightarrow X$ some bundle with connection $\nabla $ and a continuous
fibrewise metric. There exist constants $\varepsilon ,A>0$ such that, if a smooth section $\phi \in \Gamma (Q) $ satisfies:

\begin{list}{\labelitemi}{\leftmargin=1em}
        \item[(1)] 
$\Vert \phi \Vert _{C^{0}\left( V\right) }\leq \varepsilon $;        
        \item[(2)] 
$\vert \Delta \phi \vert \leq f\left( \left\vert \nabla
\phi \right\vert \right) $ on $V$, for some non-decreasing function $f:
\mathbb{R}^{+}\rightarrow \mathbb{R}^{+}$;        
        \item[(2')] 
assumption (2) remains valid under local rescalings, in the sense that, on every ball $B_{r}\subset V$, it still holds
for some function $\tilde{f}$ after the radial rescaling 
$\tilde{\phi}\left( \tilde{x}\right) := \phi
\left( mx\right) $, $m>0$;
\end{list}
then 
\begin{eqnarray*}
        \left\Vert \phi \right\Vert _{C^{1}\left( V^{\prime }\right) }
        &\leq& 
        A\left\Vert \phi \right\Vert _{C^{0}\left( V\right) }.  
\end{eqnarray*}

\begin{proof}
I first contend that $\phi $ obeys an \emph{a priori} bound
\begin{equation*}
        \left\vert \left( \nabla \phi \right) _{x}\right\vert r\left( x\right)         \leq
        1,\quad \forall x\in V
\end{equation*}
where $r\left( x\right) :V\rightarrow \mathbb{R}$ is the distance to $\partial V$. Since the term on the left-hand side is zero on $\partial V$,
its supremum is attained at some $\hat{x}\in V$ (possibly not unique).
Write \begin{displaymath}
        m:= \left\vert \left( \nabla \phi \right) _{\hat{x}}\right\vert,
        \quad 
        R=r\left( \hat{x}\right) 
\end{displaymath}
and suppose, for contradiction, that $R>\frac{1}{m}$. If that is the case, then we rescale the ball $B_{R}\left( \hat{x}\right) $ by the factor $m$, obtaining a rescaled local section $\tilde{\phi}$ defined in $\tilde{B}_{mR}\supset \tilde{B}_{1}$. In
this picture, any point in $\tilde{B}:= \tilde{B}_{\frac{1}{2}}$ is
further from $\partial V$ than $\frac{R}{2}$, hence, by definition of $\hat{x}$, $\Vert \nabla \tilde{\phi}\Vert _{C^{0}\left( \tilde{B}\right)}\leq 2$. 
By (2) and (2'), there exists $L>0$ such
that 
$\Vert \Delta \tilde{\phi} \Vert _{C^{0}\left( \tilde{B}\right)}\leq L$,
and elliptic regularity gives
\begin{equation*}
        \Vert \nabla \tilde{\phi}\Vert _{C^{0,\alpha }
        \left( \tilde{B}\right) }\leq c_{\alpha }
        .\left( L+\varepsilon \right) 
        := \tilde{c}_{\alpha }
\end{equation*}
using assumption (1). Now, the rescaled gradient at $\hat{x}$ has norm $\vert ( \nabla \tilde{\phi}) _{\hat{x}}\vert =1$ so,
taking $\alpha =\frac{1}{2}$ (say) in a smaller ball of radius 
$\rho =(\frac{1}{2\tilde{c}_{\frac{1}{2}}})^{^2}$, 
\begin{equation*}
        \vert ( \nabla \tilde{\phi}) _{x}\vert 
        \geq 
        1-\tilde{c}_{\frac{1}{2}}.\rho ^{\frac{1}{2}}
        \geq 
        \frac{1}{2},\quad \forall x\in \tilde{B}_{\rho }.
\end{equation*}
This means $\vert \tilde{\phi}\vert $ varies by some definite $
\delta >0$ inside $\tilde{B}_{\rho }$ and we reach a contradiction
choosing $\varepsilon <\delta $. So
\begin{equation*}
        \left\vert \left( \nabla \phi \right) _{x}\right\vert 
        \leq 
        \left(\inf\limits_{\partial U}r\right) ^{-1},
        \quad \forall x\in U\Subset V
\end{equation*}
for some open set $U\Supset V^{\prime }$. To conclude the proof, it
suffices to control the $L^{2}-$norm of $\nabla \phi $ on $U$: 
\begin{eqnarray*}
        \left( cst.\right) \left\Vert \nabla \phi \right\Vert^2 _{C^{0}\left(
V^{\prime }\right) } &\leq &\left\Vert \nabla \phi \right\Vert ^2_{L^{2}\left(
U\right) }=\int_{U}\left\langle \nabla \phi ,\nabla \phi \right\rangle 
=\int_{U}\left\langle
\phi ,\Delta \phi \right\rangle \\
&\leq &\left[f\left(\left\Vert \nabla \phi \right\Vert _{C^{0}\left( U\right)
}\right)\right]^{2}\left\Vert \phi \right\Vert _{L^{2}\left( V^{\prime }\right) }^{2}
\end{eqnarray*}
and the last term is obviously bounded by $\left( cst.\right) \left\Vert
\phi \right\Vert _{C^{0}\left( V\right) }^{2}$.
\end{proof}

\begin{equation}        
\fbox{$
\begin{array}{c}
        \left\Vert\Delta_K H \right\Vert 
        \leq (cst.)\left[ \left( \Vert\hat{F}_H\Vert +1 \right)
        \left\Vert H \right\Vert + \left\Vert \nabla_{K}H\right\Vert ^{2}
        \Vert H^{-1}\Vert \right]  
\end{array}
$}
\end{equation}

\begin{equation}        
        \left.\sigma\left(H\left( t\right) ,H_{0}\right) \right\vert 
        _{\partial W_{S}}
        \leq 2\left( \mathbf{e}^{\tilde{B}T\mathbf{e}^{\frac{1}{2}(T-S)}}-1 \right)
        =
        O\left(\mathbf{e}^{-S}\right) .  
\end{equation}

$F_{H_{S}}$ is bounded in $C^k\left( W_{S}\right) $, uniformly in $t\in[0,T] $, for each $k\geq 0$.
\begin{proof}
By induction on $k$:

\underline{$k=0$}: following [ASDYM], we obtain a uniform
bound on $e_S(t):= \left\vert F_{H_{S}\left( t\right)
}\right\vert ^{2}$, using the fact that 
\begin{equation*}
\left( \frac{d}{dt}+\Delta \right) e_{S}\leq \left( cst.\right) \left( (e_{S})^{\frac{3
}{2}}+e_{S}\right)
\end{equation*}
[ASDYM], and consequently
\begin{equation}
e_{S}\left( t\right) \leq \left( cst.\right) \left( 1+\int_{0}^{t}\left\Vert
K_{t-\tau }\right\Vert _{L^{p}\left( W_{S}\right) }\Vert \left(e_S\right)^{\frac{3}{2}
}+e_S\Vert _{L^{q}\left( W_{S}\right) }\right) ,

\end{equation}
where $K_{t}$ is the heat kernel associated to $\frac{d}{dt}+\Delta $ and $
\frac{1}{p}+\frac{1}{q}=1$. On the complete [\emph{Theorem 11}] $6-$dimensional Riemannian manifold $W_{S}$, $K_{t}$ satisfies 
[Eels and Sampson] the diagonal condition
\begin{equation*}
K_{t}\left( x,x\right) \leq \frac{\left( cst.\right) }{t^{3}},\qquad \forall
x\in W_{S}
\end{equation*}
of \emph{Theorem 60} in Appendix App Gaussian upper bound, which gives a `Gaussian' bound on the heat kernel. So, fixing $C>4$ and denoting $
r\left( .,.\right) $ the geodesic distance, we have 
\begin{equation*}
K_{t}\left( x,y\right) \leq \frac{\left( cst.\right) }{t^{3}}\exp \left\{ -
\frac{r\left( x,y\right) ^{2}}{Ct}\right\} ,\qquad \forall x,y\in W_{S}.
\end{equation*}
Hence, for each $x\in W_{S}$, we obtain the bound
\begin{eqnarray*}
\left\Vert K_{t}\left( x,.\right) \right\Vert _{L^{p}\left( W_{S}\right) }
&\leq &\frac{\left( cst.\right) }{t^{3}}\left( \int_{W_{S}}\exp \left\{ -p
\frac{r\left( x,y\right) ^{2}}{Ct}\right\} dy\right) ^{\frac{1}{p}} \\
&\leq &\frac{\left( cst.\right) }{t^{3}}\left( \int_{0}^{\infty }\left( 
\tfrac{Ct}{p}\right) ^{3}u^{5}\mathbf{e}^{-u^{2}}du\right) ^{\frac{1}{p}} \\
&\leq &\tilde{c}_{p}\;t^{\frac{3}{p}\left( 1-p\right) }.
\end{eqnarray*}
Now, $p<\frac{3}{2}\Leftrightarrow \frac{3}{p}\left( 1-p\right) >-1$, in
which case
\begin{equation*}
\int_{0}^{T}\left\Vert K_{t}\left( x,.\right) \right\Vert _{L^{p}\left(
W_{S}\right) }dt\leq c_{p}\left( T\right) .
\end{equation*}
Inequality $\left( 26\right) $ gives the desired
result provided $\left(e_S\right)^{\frac{3}{2}}\in L^{q}\left( W_{S}\right) $ for some $q>3$
; this means $F_{H_{S}\left( t\right) }\in L^{\tilde{q}}\left( W_{S}\right) $
for some $\tilde{q}>9$, which is guaranteed by \emph{Corollary 27}.

\underline{$k\Rightarrow k+1$}: The general recurrence step is identical to 
[ASDYM], using the maximum principle [\emph{Lemma 21}] with boundary conditions.
\end{proof}

If $\left\{ H_{S}\left( t\right)\right\} _{0\leq t<T}$ is a solution of $\left( 15\right) $ with Dirichlet condition (16) on $\partial W_{S}$, then the $H_{S}\left( t\right) $ are bounded in $L_{2}^{p}\left( W_{S}\right) $ uniformly in $t$, for all $1\leq p<\infty $, and $H_{S}\left( T\right)$ is of class $C^{1}$.
\begin{proof}
By \emph{Corollary 23 }and $\left( 18\right) $, $\left\{ H_{S}\left( t\right) \right\} _{0\leq t<T}$
satisfies respectively (1) and (2) in  \emph{Lemma 26}.
\end{proof}

Let $M$ be an arbitrary connected Riemannian $n-$manifold, $x,y\in M$         and $0\leq T\leq\infty$; if there exist suitable [see below] real         functions $f$ and $g$ satisfying the `diagonal' conditions 
        \begin{eqnarray*}
                K_t(x,x)\leq\frac{1}{f(t)}\quad \text{and} \quad K_t(y,y)\leq\frac{1}{g(t)},\quad         \forall t\in \left(0,T\right),
        \end{eqnarray*}
        then, for any $C>4$, there exists $\delta=\delta(C)>0$ such that
        \begin{eqnarray*}
                \boxed{ K_t(x,y) \leq \frac{(cst.)}{\sqrt{f(\delta t)g(\delta t)}}\exp\left\{-\frac{r(x,y)^2}{Ct}\right\},                 \quad \forall t\in \left(0,T\right)}
        \end{eqnarray*}
        where $(cst.)$ depends on the Riemannian metric only.

For $W=\bar{W}\setminus D$ as in \emph{Definition def base manifold (W, w)}: 
\begin{enumerate}
        \item
        $W$ admits a complete Ricci-flat K\"{a}hler metric $\omega $;
        \item
        along the cylindrical end $D\times S_{\alpha }^{1}\times 
        \left(\mathbb{R}_{+}\right) _{s}$, the K\"{a}hler form $\omega $
         and its holomorphic volume form $\Omega $ are 
        \emph{exponentially asymptotic} to those of the (product) cylindrical metric induced from $D$:
        \begin{eqnarray}
        \begin{array}{r c l}      
                \omega _{\infty } &=&\kappa _{I}+ds\wedge d\alpha \\
                \Omega _{\infty } &=&\left( ds+\mathbf{i}d\alpha \right)                 \wedge \left(\kappa _{J}+\mathbf{i}\kappa _{K}\right) \text{;}
        \end{array}
        \end{eqnarray}
        \item
        $\textnormal {Hol\,}\left( \omega \right) =SU\left( 3\right) $, i.e., 
        $W$ is Calabi-Yau.
\end{enumerate}

Under the Dirichlet conditions (16), the limit
metric $H_{S}\left( T\right) $ is smooth.

\begin{proof}
We apply \emph{Lemma 29} to the one-parameter family $\{H_S(t)\}_{0\leq t\leq T}$ of Hermitian metrics on the restriction $\mathcal{E}\to W_S$ given by \emph{Lemma 24}. Then 
\emph{Corollary 27} gives hypothesis (1), \emph{
Lemma 28} gives (2) and the
Dirichlet condition on $\partial W_{S}$ gives (3), as $H_{0}$ is smooth.
\end{proof}

For $0\leq I\leq \infty$, let $\left\{ H_{i}\right\}_{0\leq i< I} $ be a
one-parameter family of Hermitian metrics on a holomorphic vector bundle $\mathcal{E}\rightarrow X$ over a compact (real) $2n-$dimensional K\"{a}hler manifold with boundary
such that
\begin{enumerate}
        \item
        $\left\{ H_{i}\right\} $ is bounded in $L_{2}^{p}\left( X\right), $ for all $1\leq p<\infty $, and $\displaystyle H_{i}\underset{i\rightarrow I}{\overset{L_{2}^{p}(X)}{\longrightarrow }}H$, where $H$ is a continuous metric,        
        \item
        $\{\hat{F}_{H_{i}}\}$is bounded in $L_{k}^{p}\left( X\right) $, for each $(p,k)\in [1,\infty[\times\mathbb{N}$, 
        \item
        $\{H_{i}\}$is bounded in $L_{k}^{p}\left( \partial X\right) $, for each $(p,k)\in [1,\infty[\times\mathbb{N}$; 

\end{enumerate}
then $\displaystyle H_{i}\underset{i\rightarrow I}{\overset{C^\infty(X)}{\longrightarrow }}H$ and $H$ is smooth.
\begin{proof}
Fixing $p>2n$, I will prove the following statement by induction in $k$:
\begin{equation*}
\begin{tabular}{l}
$\left\Vert H_i\right\Vert _{L_{k+2}^{p}(X)}$ and $\Vert H_i^{-1}\Vert
_{L_{k}^{p}(X)}$ are bounded uniformly in $i$, $\forall k\geq0$.
\end{tabular}
\end{equation*}
The first hypothesis gives step $k=0$, as well as $\Vert H_i^{-1}\Vert
_{L_{1}^{p}(X)}<\infty$, since the Sobolev embedding implies $H_i$ is in $C^1$. Now, assuming the statement up
to step $k-1\geq0$ implies in particular $k\geq1>\frac{2n}{p}$, which authorises the multiplication $L^p_k\times L^p_{k-1}\to L^p_{k-1}$ and so 
\begin{eqnarray*}
        \Vert H_i^{-1}\Vert _{L_{k}^{p}}
        &=&\Vert H_i^{-1}\Vert_{L^{p}}
        +\Vert \nabla \left( H_i^{-1}\right)\Vert_{L_{k-1}^{p}}\\
        &\leq &\Vert H_i^{-1}\Vert _{L^{p}}
        +\Vert H_i^{-1}\Vert_{L_{k-1}^{p}}^{2}
        \Vert \nabla H_i\Vert _{L_{k}^{p}} \\
        &\leq &\Vert H_i^{-1}\Vert _{L_{k-1}^{p}}
        \left( 1+\Vert H_i^{-1}\Vert _{L_{k-1}^{p}}
        \left\Vert H_i\right\Vert _{L_{k+1}^{p}}\right)
\end{eqnarray*}
so $\Vert H_i^{-1}\Vert _{L_{k}^{p}}$ is bounded. On the other hand,
elliptic regularity on manifolds with boundary and $\left( 25\right) $, with $K=H_0$, give
$$
\begin{array}{rl}
\left\Vert H_i\right\Vert _{L_{k+2}^{p}}^{2} \leq &c_0
        \left(\left\Vert \Delta H_i\right\Vert _{L_{k}^{p}}^{2}
        +\left\Vert H_i\right\Vert_{L_{k+1}^{p}}^{2}
        +\left\Vert H_i\right\Vert _{L_{k+\frac{3}{2}}^{p}
        \left(\partial X\right) }^{2}\right) \\
        \leq &c_0
        \left[ \left\Vert H_i\right\Vert _{L_{k+1}^{p}}^{2}
        \left(1+\left( 1+\Vert \hat{F}_{H_i}\Vert _{L_{k}^{p}}
        +\left\Vert H_i\right\Vert _{L_{k+1}^{p}}
        \Vert H_i^{-1}\Vert _{L_{k}^{p}}\right)^{2}\right)+
        \left\Vert H_i\right\Vert 
        _{L_{k+\frac{3}{2}}^{p}\left( \partial X\right) }^{2} \right]\end{array}
$$
where $c_0$ depends on $H_0$ and $X$ only, and all those terms are bounded by assumption. 

Since $p$ could be chosen arbitrarily big, the family $\{H_{i}\}$ is uniformly bounded in each $C^r$. But we know it converges to $H$ in $C^1$, hence in fact it converges in $C^\infty$ and the limit is
smooth.
\end{proof}

Take $B$ and $\epsilon$ as in (27); then
\begin{equation*}
        \hat{e}_t \leq \left(B\mathbf{e}^{t}\right)\epsilon 
        \quad \text{on}\quad W.
\end{equation*}
\begin{proof}
The statement is obvious on $W_{0}$. For any $s_0,t_0\geq 0$, take $T=S>\max
\left\{ s_0,t_0\right\} $, let $\Sigma _{S}:= W_{S}\smallsetminus W_{0}$ and
consider on $\Sigma _{S}\times \left[ 0,T\right] $ the comparison function $
g\left( t,s\right) := B\mathbf{e}^{t-s}$. Using the Weitzenb\"ock formula one shows that  $\left( \frac{d}{dt}+\Delta \right) 
\hat{e}_{S}\leq 0$ [cf. $(19)$], where $\hat{e}_{S}=\vert \hat{F}_{H_S} \vert^2$ and $H_S$ is a solution of our flow on $W_S$ as in $\emph{Lemma}$\emph{\ 24}. For $\psi := $ $\hat{e}
_{S}-g$, one clearly has $\left( \frac{d}{dt}+\Delta \right) \psi \leq 0\ $(recall that our sign convention for the Laplacian is $\Delta
\overset{loc}{=}\mathbf{-}\sum\frac{\partial ^{2}}{\partial x_{i}^{2}}$) and, by the maximum principle [\emph{Lemma 16}],
\begin{equation*}
\psi \leq \max\limits_{\partial \left( \left[ 0,T\right] \times \Sigma
_{S}\right) }\left\{ \hat{e}_{S}-B\mathbf{e}^{t-s}\right\} \leq 0.
\end{equation*}
To see that the r.h.s. is zero, there are four boundary terms to check:
\begin{description}
        \item[\quad$s=S:$]
the Dirichlet condition means $\hat{e}_{S}\left(
t,S\right) =0$, $\forall t>0$, so $\psi \left( t,S\right) \leq 0$;

        \item[\quad$s=0:$]
$\psi \left( t,0\right) \leq B\left( 1-\mathbf{e}^{t}\right)\leq 0$;

        \item[\quad$t=0:$]
$\left( 27\right) $ gives $\psi
\left( 0,s\right) \leq 0$;

        \item[\quad$t=T:$]
again by \emph{Corollary 17 }we have 
$\psi \left( T,s\right) \leq B\left( 1-\mathbf{e}^{T-s}\right) \leq 0$.
\end{description}
This shows that $\hat{e}_{S}\left( t,s\right) \leq B\mathbf{e}^{t-s}$ on $\Sigma_S\times[0,T]$. Take $T=S\rightarrow \infty $.
\end{proof}

If a smooth solution $H_{S}\left( t\right) $ to $\left( 15\right) $ on $W_{S}$, with Dirichlet boundary
conditions (16), is defined for $t\in[0,T[$, then 
$H_{S}\left( t\right) 
\underset{t\to T}{\overset{C^{0}}{\longrightarrow }}H_{S}\left( T\right)$ and $H_{S}\left( T\right) $ is continuous.
\begin{proof}
The argument is analogous to [ASDYM]. As discussed in \emph{Remarks 18 }and \emph{20}
, it suffices to show that $\sup \sigma \left( H_{S}\left( t\right)
,H_{S}\left( t^{\prime }\right) \right)\to0 $ when $t^{\prime
}>t\rightarrow T$. Clearly 
$$
f_{t}:=\sup\limits_{W_{S}}
        \sigma \left(H_{S}\left( t\right) ,H_{S}\left( t+\tau \right) \right)
$$ 
satisfies the (boundary) conditions of \emph{Lemma 16},
 so it is decreasing and 
\begin{equation*}
        \sup_{W_{S}}\sigma\left(H_{S}\left(t\right),
        H_{S}\left(t+\tau\right)\right)
        <\sup_{W_{S}}\sigma\left( H_{S}\left( 0\right) ,
        H_{S}\left( \tau \right)\right)
\end{equation*}
for all $t,\tau ,\delta >0$ such that $0<T-\delta <t<t+\tau <T$. Taking $
\delta <\varepsilon $ in \emph{Proposition 15}
we ensure continuity of $H_{S}\left( t\right) $ at $t=0$, so the right-hand
side is arbitrarily small for all $t$ sufficiently close to $T$. Hence the family $\left\{H_{S}\left( t\right)\right\}_{t\in[0,T[} $ is uniformly Cauchy as $t\rightarrow T$ and the limit is continuous.
\end{proof}

Let $\left\{ H_{S}\left( t\right) \right\} _{0\leq t<T}$ be a smooth solution to $\left( 15\right)$ on $W_{S}$. Then $\sup\limits_{W_{S}}\hat{e}_{t}$ is non-increasing with $t$; in fact, there exists $B>0$, independent of $S$ and $T$, such that
\begin{equation}        
        \sup_{W_{S}}\vert\hat{F}_{H_{S}(t)}\vert^{2}\leq B.
\end{equation}
\begin{proof}
Using the Weitzenb\"{o}ck formula [4-manifolds], one finds
\begin{equation}       
        \left( \frac{d}{dt}+\Delta \right) \hat{e_{t}}
        =-\vert d_{H_{S}\left(t\right) }^{\ast }F_{H_{S}
        \left( t\right) }\vert ^{2}\leq 0.
\end{equation}
At the boundary $\partial W_{S}$, for $t>0$, the Dirichlet condition $\left( 16\right) $ means precisely that $\left. H_{S}\right\vert
_{\partial W_{S}}$ is constant, hence the evolution equation gives $\left. \hat{e}_{t}\right\vert _{\partial W_{S}}=\left. \vert H_{S}^{-1}\dot{H}
_{S}\vert ^{2}\right\vert _{\partial W_{S}}\equiv 0$. Then $
B:=\sup\limits_{W_{S}}\hat{e}_{0}$.
\end{proof}

Let $X$ be a compact Riemannian
manifold with boundary and suppose $f\in C^{\infty }\left( \mathbb{R}
_{t}^{+}\times X\right) $ is a nonnegative function satisfying:
\begin{equation*}       \index{maximum principle}
        \left(\frac{d}{dt}+\Delta \right) f_{t}\left( x\right) \leq 0,
        \quad \forall \left(t,x\right) \in \mathbb{R}_{t}^{+}\times X
\end{equation*}
and the Dirichlet condition:
\begin{equation*}
        \left. f_{t}\right\vert _{\partial X}=0.
\end{equation*}
Then either $\sup\limits_{X}f_{t}$ is a decreasing function of $t$ or $
f\equiv 0$.

\begin{equation}        
        H\mid _{\partial W_{S}}=H_{0}\mid _{\partial W_{S}}.  
\end{equation}

If $H_{1}(t) $ and $H_{2}(t)$ are solutions of evolution equation $\left( 15\right) $, then $\sigma (t) =\sigma \left( H_{1}(t),H_{2}(t) \right)$ satisfies
\begin{equation*}
        \left( \frac{d}{dt}+\Delta \right) \sigma \leq 0.
\end{equation*}

Equation $\left( 15\right) $
admits a smooth solution $H_{S}\left( t\right) $, $t\in \left[ 0,\varepsilon
\right[ $, for $\varepsilon $ sufficiently small.
\begin{proof}
By the K\"{a}hler identities, $\left( 15\right) $ is
equivalent to the parabolic equation
\begin{eqnarray*}       \index{evolution equation!is nonlinear parabolic}
        \frac{\partial h}{\partial t} 
        &=&-\left\{ \Delta _{0}h+\mathbf{i}\left( \hat{F}_{0}.h
        +h.\hat{F}_{0}\right) +2\mathbf{i}\Lambda 
        \left( \bar{\partial}_{0}h.h^{-1}.\partial _{0}h\right) \right\}\\
        h\left( 0\right)  &=&I,\qquad \left. h\right\vert _{\partial W_{S}}=I.
\end{eqnarray*}
for a positive self-adjoint endomorphism $h\left( t\right)
=H_{0}^{-1}H_{S}\left( t\right) $ of the bundle, with Hermitian metric $H_{0}$. Then the claim is an instance of the general theory  [Hamilton].
\end{proof}

