The function $\mathcal{N}_{W}\left( H_{t}\right) $ 
is well-defined, $\forall t\in \left[ 0,\infty\right[ $, and
\begin{equation*}
        \frac{d}{dt}\mathcal{N}_{W}\left( H_{t}\right) 
        =-\frac{2}{3}\Vert \hat{F}_{H_{t}}\Vert _
        {L^{2}\left( W\right) }^{2}.
\end{equation*}
\begin{proof}
Using the evolution equation $\left( 36\right)$:
\begin{eqnarray*}
        \frac{d}{dt}\mathcal{N}_{W}\left( H_{t}\right) 
        &=& \left( \rho _{W}\right)_{H_{t}}\left( \dot{H}_{t}\right) 
        = \int_{W}\Phi _{t}\wedge \omega ^{2} \\
        &=& 2\int_{W}\textnormal {tr\,}\underset{2\hat{F}_{H_{t}}}{\underbrace{\mathbf{i}
        H_{t}^{-1}.\dot{H}_{t}}}.\underset{\frac{1}{6}\hat{F}_{H_{t}}\:d\textnormal {Vol\,}_\omega}{\underbrace{F_{H_{t}}
        \wedge \omega ^{2}}} 
        = \frac{2}{3}\int_{W}\textnormal {tr\,}\hat{F}_{H_{t}}^{2}\:d\textnormal {Vol\,}_\omega \\
        &=& -\frac{2}{3}\Vert \hat{F}_{H_{t}}\Vert
        _{L^{2}\left( W\right)}^{2}
\end{eqnarray*}
and this is finite, as $\hat{F}_{H_{t}}$ decays exponentially along $W$ [\emph{Proposition 32}].
\end{proof}

Under the hypotheses of  \emph{Claim 44}, there exists a constant $C_\infty$, independent of $t$ and $z$, such that
\begin{displaymath}
L_t \leq C_\infty , \quad \forall t\in \left]0,\infty \right[.
\end{displaymath}

\begin{proof}

Either $L_t$ is uniformly bounded in $t$ and there is nothing to prove, or  $\displaystyle\frac{\mu_{\infty}\left( A_t \right)}{\sqrt{L_{t}}}\underset{t\to\infty}{\longrightarrow} c'$ and so (a subsequence of) the family of sets $\left\{A_t\right\}_{0<t<\infty}$ gets arbitrarily $\mu_\infty-$large as $t\rightarrow \infty$.
In the latter case, the term $O\left( \frac{1}{L_t} \right)$ in the \emph{Claim} becomes negligible, so
\begin{eqnarray*}
        c.\mu_{\infty}\left( A_t \right) 
        &\leq& \int_{\Sigma_t} \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2 +R_0\right) 
        \:d\text{V}_{tub}.
\end{eqnarray*}

 Let us examine the energy contributions of each component of $W=W_0\cup W_\infty$ [cf. (10)]. On one hand, the complement $W_\infty\smallsetminus\Sigma_t$ is a cylindrical domain, which by \emph{Lemma 56}  has nonnegative energy in the model metric $\:d\text{V}_{tub}$; so we may extend the above integral over $W_\infty$. On the other hand, in the actual metric $\:d\textnormal {Vol\,}_\omega$ we have:
\begin{eqnarray*}
        E(t)&=&\left(\int_{W_0}+\int_{W_\infty} \right)
        \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2 \right) 
        \:d\textnormal {Vol\,}_\omega\\
        &\geq&
       -\left\Vert F_0\right\Vert^2 _{L^2(W_0,\omega)} 
        + \int_{W_\infty}
        \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2\right) 
        \:d\textnormal {Vol\,}_\omega.
\end{eqnarray*}
To connect both facts, consider the ratio of volume forms
over $W_\infty$
$$
\:d\text{V}_{tub}=f.\:d\textnormal {Vol\,}_\omega
$$
and extend it to a  bounded positive function $f:W\to\mathbb{R}^+$. Then 
\begin{eqnarray*}
        c.\mu_{\infty}\left( A_t \right) 
        &\leq& \left(\sup_W f\right)\left(E(t)
        +\left\Vert F_0\right\Vert^2 _{L^2(W_0,\omega)} 
        +\left\Vert R_{0}\right\Vert_{L^1(W,\omega)}\right)
\end{eqnarray*}
 and we know from the negative energy condition (47) that this is bounded above, uniformly in $t$. Hence the cylinder $\Sigma_t$ cannot stretch indefinitely and, by contradiction, there must exist a uniform upper bound$$ 
C_\infty \simeq 
\left[
\frac
{\sup f} 
{c.c''}
\left(\left\Vert F_0\right\Vert^2 _{L^2(W_0)} 
+\left\Vert R_{0}\right\Vert_{L^1(W)}
\right)
\right]^2.
$$
\end{proof}

There are constants $c,c'>0$  independent of $t$ and $z$ such that, for every $t \in \left]0,\infty \right[$, there exists an open set $A_t\subset\tau(W_\infty)\subset\mathbb{C}P^{1}$   of parameters [cf. (12)]  satisfying:
