Let $\Sigma=\tau^{-1}(A)\subset W_\infty$ be any cylindrical domain along the tubular end, parametrised by $A\subset\mathbb{C}P^{1} $; then
\begin{eqnarray*}
        \int_{\Sigma} \left(\left\vert F_t\right\vert^2
        - \left\vert F_0 \right\vert^2 +R_0\right) 
        \:d\text{V}_{tub}         
        &\geq&
        2\int_{A} \Vert \widehat{F_{t \vert s}} \Vert^2_{L^2(D_s)}
        ds\wedge d\alpha 
\end{eqnarray*}
where $R_0$ decays exponentially along the tube. 
\begin{proof}
Isolating the component of curvature along each transversal slice $D_s$ in the asymptotia (28) of $F_{0}$ , we have $\left\vert F_0 \right\vert^2 =\vert F_{0\vert s} \vert^2+R_{0}$ over $W_\infty$, where the remainder indeed satisfies $R_0 = O\left(e^{-s}\right)$. The Hodge-Riemann property  (48) and the decomposition (49) then give, by Fubini's theorem,
\begin{eqnarray*}
        \int_{\Sigma} \left(\left\vert F_0 \right\vert^2 -R_0 \right)
        \:d\text{V}_{tub}
        &=& \int_{A} \left\{\int_{D_{s}}\left\vert F_{0\vert s} \right\vert^2
        \left.\:d\textnormal {Vol\,}_\omega\right\vert_{D_s}\right\} ds\wedge d\alpha \\
        &=& \int_{A} \left\langle c_2\left( \left.\mathcal{E}\right\vert_{D_s}\right),\left[ D_s \right]\right\rangle
        ds\wedge d\alpha.        
\end{eqnarray*}
On the other hand, again by (48), 
\begin{eqnarray*}
        \int_{\Sigma } \left\vert F_t \right\vert^2 
        \:d\text{V}_{tub}
        & \geq& \int_{\Sigma } \left\vert F_{t\vert s} \right\vert^2
        \:d\text{V}_{tub}\\
        &= &\int_{A} \left\{\int_{D_s} \left\vert F_{t\vert s}\right\vert^2
        {\left.\:d\textnormal {Vol\,}_\omega\right\vert_{D_s}}\right\} ds\wedge d\alpha \\
        &\geq &\int_{A}\left\{ \left\langle c_2 \left( \left.\mathcal{E}\right\vert_{D_s}         \right),\left[ D_s \right]\right\rangle 
        +2 \int_{D_s}\vert \widehat{F_{t\vert s}} \vert^2 \left.\:d\textnormal {Vol\,}_\omega\right\vert_{D_s}         \right\} ds\wedge d\alpha,
\end{eqnarray*}
using the normalisation $c_1(\left.\mathcal{E}\right\vert_{D_s})=0$ [cf. discussion following (17)] so that only $c_2 \left( \left.\mathcal{E}\right\vert_{D_s}\right)$ contributes to the integral of $\textnormal {tr\,}F_{t\vert s}^{2}$. Comparing and cancelling the topological terms yields the result.\end{proof}

A solution $\left\{H_t\right\}$ to the evolution equation
given by \emph{Theorem 36} satisfies
the \emph{negative energy} condition\begin{eqnarray}        
        E(t):= \int_{W}
        \left( 
        \left\vert F_{H_{t}}\right\vert^{2}
        -
        \left\vert F_{H_{0}}\right\vert ^{2}
        \right) \:d\textnormal {Vol\,}_\omega
        &\leq& 
        0,\qquad \forall t\in \left]0,\infty \right[.
\end{eqnarray}
\begin{proof}
The curvature of a Chern connection splits orthogonally as $F=\hat{F}.\omega  \oplus  F^{\perp }$ in $\Omega ^{1,1}\left( \textnormal {End\,}\mathcal{E}\right)$, so
$\left\vert F\right\vert ^{2}=\vert F^{\perp }\vert
^{2}+\vert \hat{F}\vert ^{2}$
(setting $\left\vert \omega \right\vert =1$). On the other hand, the Hodge-Riemann  equation $\left( 52\right) $ [see \emph{Appendix A}] reads
 \begin{equation*}
        \textnormal {tr\,}F^{2}\wedge \omega 
        =\left( \vert F^{\perp }\vert^{2}
        -\vert \hat{F}\vert ^{2}\right) \omega ^{3}.
\end{equation*}
Comparing we find $\left\vert F\right\vert ^{2}\omega ^{3}=\textnormal {tr\,}F^{2}\wedge \omega +2\vert \hat{F}\vert ^{2}\omega ^{3}$ [cf. \emph{Subsection Sub energy bounds}], so
\begin{eqnarray*}
        E(t)&=&\int_{W}\left(\textnormal {tr\,}F_{H_{t}}^{2}
        -\textnormal {tr\,}F_{H_{0}}^{2}\right)\wedge \omega
        +2 \int_{W}\left(\hat{e}_t - \hat{e}_0\right)\omega ^{3}\\
        \overset{\frac{d}{dt}}{\Longrightarrow}\quad
        \dot{E}(t)&\leq&\int_W \left(-\mathbf{i}\bar{\partial}\partial           \Phi_t\right)\wedge\omega +2\int_W\left(-\Delta\hat{e}_t\right)\omega^{3}\\
        &\leq&\lim_{S\rightarrow\infty}\int_{\partial W_S}
        2\left[\partial \textnormal {tr\,} \left(\hat{F}_{H_t}.F_{H_t}\right)\wedge\omega
        +\frac{\partial\hat{e}_t}{\partial\nu} \left.\:d\textnormal {Vol\,}_\omega\right\vert_{\partial         W_S}\right]\\
        &=&0
\end{eqnarray*}
using \emph{Lemma 40}
along with its \emph{Proof} and $\left(\frac{d}{dt}+\Delta\right)\hat{e}_t \leq 0$ as in $(19)$, then complex integration by parts [\emph{Lemma 59} in \emph{Appendix App exterior algebra}] and the Gauss-Ostrogradsky theorem, and finally the exponential decay $\hat{F}_{H_t} \overset{C^\infty}{\underset{S\rightarrow\infty}{\longrightarrow}} 0$, a direct consequence from \emph{Proposition 32} and \emph{Corollary 35}. This shows that $E(t)$ is non-increasing, while obviously $E(0)=0$.
\end{proof}

