Let $X^{n}\subseteq W$ be a compact complex (sub)manifold (possibly $n=3$), $\Phi $ a $\left( 1,1\right)-$form, $\Omega $ a closed $\left( n-2,n-2\right) -$form and $f$ a
meromorphic function on $X$; then 
\begin{equation*}
        \int_{X}
        \Phi \wedge dd^{c}f\wedge \Omega 
        =\int_{X}
        f.\left( -\mathbf{i}\bar{\partial}\partial \Phi \right) \wedge \Omega         +\mathbf{i}\int_{\partial X}
        \left( \Phi \wedge \bar{\partial}f+f.\partial \Phi \right)\wedge\Omega.
\end{equation*}
\begin{proof}
By the Leibniz rule and Stokes' theorem, using $d=\partial +\bar{\partial}$
and taking account of bi-degree, we have
\begin{eqnarray*}
\int_{X}\Phi \wedge dd^{c}f\wedge \Omega &=&\int_{X}\Phi \wedge \mathbf{i}
\partial \bar{\partial}f\wedge \Omega \\
&=&\mathbf{i}\int_{\partial X}\Phi \wedge \bar{\partial}f\wedge \Omega 
\underset{\left( \ast \right) }{\underbrace{-\int_{X}\mathbf{i}\partial \Phi
\wedge \bar{\partial}f\wedge \Omega }}
\end{eqnarray*}
and again
\begin{eqnarray*}
\left( \ast \right) &=&\mathbf{i}\int_{\partial X}f.\partial \Phi \wedge
\Omega +\int_{X}f.\left( -\mathbf{i}\bar{\partial}\partial \Phi \right)
\wedge \Omega .
\end{eqnarray*}
\vspace{-1.3cm}\[\]
\end{proof}

Let $H$ be a Hermitian bundle
metric and  $h$ an element of $\mathcal{I}_0$ and denote $
\tau := H^{-1}h$; then the curvature of the
Chern connection of $H$ varies, to first order, by
\begin{equation*}
        F_{H+h}=F_{H}
        +\bar{\partial}\partial _{H}\tau 
        +O( \left\vert\tau\right\vert ^{2}).
\end{equation*}

\begin{proof}
Set $g=H^{-1}\left( H+h\right) =1+\tau $, so that [4-manifolds][ASDYM]
\begin{equation*}
F_{H+h}=F_{H}+\bar{\partial}\left( g^{-1}\partial _{H}g\right) .
\end{equation*}
Observing that $g^{-1}=1-\tau +O( \left\vert\tau\right\vert ^{2}) $, we expand the
variation of curvature:
\begin{eqnarray*}
\bar{\partial}\left( g^{-1}\partial _{H}g\right) &=&-\left( g^{-1}.\bar{
\partial}g.g^{-1}\right) \partial _{H}g+g^{-1}\bar{\partial}\partial _{H}g \\
&=&-\left( 1-\tau \right) \bar{\partial}\tau \left( 1-\tau \right) \partial
_{H}\tau +\left( 1-\tau \right) \bar{\partial}\partial _{H}\tau +O(
\left\vert\tau\right\vert ^{2}) \\
&=&\bar{\partial}\partial _{H}\tau +O( \left\vert\tau\right\vert ^{2}).
\end{eqnarray*}
\vspace{-1.3cm}\[\]
\end{proof}

Let $\left(D,g\right)$ be a compact Riemannian manifold, $f\in L^\infty\left(D,\mathbb{R}^+\right)$,  $p>1$ and $x>0$; then there exists a constant $k_p=k_p\left(D,g\right)>0$ such that
\begin{displaymath}
        \left\Vert f\right\Vert_p \geq \frac{k_p}{F^x}\left\Vert f^{1+x}         \right\Vert_1
\end{displaymath}
with $\left\Vert.\right\Vert_q:=\left\Vert . \right\Vert_{L^q\left(D,g\right)},1<q\leq\infty,$ and $F:= \left\Vert f \right\Vert_\infty$.
\begin{proof}
It suffices to write
\begin{displaymath}
        \left\Vert f \right\Vert_p := \left(\int_D f^p \; d\textnormal {Vol\,}_g\right)^{\frac{1}{p}}
        \geq \left(\int_D f^p\left( \frac{f}{F} \right)^{xp}
        d\textnormal {Vol\,}_g\right)^{\frac{1}{p}} \\
        = F^{-x} \left\Vert f^{1+x} \right\Vert_p
\end{displaymath}
then apply H\"older's inequality, finding $k_p=\textnormal {Vol\,}_g(D)^{\frac{1}{p}-1}$.
\end{proof}

Given $t>0$ and $0<\epsilon<1$, let $\Sigma_{t}(\epsilon):= I_{\epsilon,t}\times D \simeq \overline{W_{S_t+\delta^+_{\epsilon,t}}\setminus W_{S_t}}$ be the finite cylinder along $W$, under the parabola $P_t$ of \emph{Lemma 52}, determined by the interval of length $\delta^+_{\epsilon,t}$ on which $(43)$ holds, and suppose ${2\mathbf{\pi}}\delta^+_{\epsilon,t}\in\mathbb{N}$; then, for each $x>0$, there exist time-uniform constants $ a_{x,\epsilon},b_{x,\epsilon}>0$ such that, if $L_t>b_{x,\epsilon}$, the following estimate holds:
\begin{equation}        
        \int_{\Sigma_{t}(\epsilon)}\bar\lambda_t^{1+x} \; 
        d\textnormal {Vol\,}_{\omega_\infty} 
        \geq a_{x,\epsilon} 
        \cdot \delta^+_{\epsilon,t}
        \cdot \left(L_t-b_{x, \epsilon} \right)^{1+x}. 
\end{equation}
\begin{proof}  
Again let me suppress the $t$ subscript, for tidiness, and work all along in the cylindrical metric $\omega_\infty$. For each $s\in I_\epsilon$, let $p_s\in \partial W_s \simeq D_s\times S^1$ be a point on the corresponding transversal slice such that the maximum $\ell(s)=\bar\lambda(p_s)$ is attained, and form the `unit' open cylinder $B_s\subset \Sigma_\epsilon$ of length $\frac{1}{2\mathbf{\pi}}$ (so that the volume integral over $B_s$ along the $S^1\times I_\epsilon$ directions is 1), centered on $p_s$, such that 
\begin{displaymath}
        \textnormal {Vol\,} B_s = \textnormal {Vol\,} \left( B_s\cap D_s \right) = \frac{1}{2} \textnormal {Vol\,} D,
\end{displaymath}
where $\textnormal {Vol\,} D\equiv \textnormal {Vol\,} D_s$ denotes the (same) four-dimensional volume of (every) $D_s$.

By \emph{Lemma 50}, $\bar\lambda$ is a weak subsolution of the elliptic problem $\Delta u=\beta$, so we may apply Moser's iteration method   [Gilb-Trud][Moser] over an open set $V$ such that $\partial W_s\subset V\subset B_s$ to obtain local boundedness of $\bar\lambda$ in terms of its $L^{1+x}(B_s,\omega_\infty)-$norm. Indeed we can choose $V$ such that:   
$$
\ell(s)
\leq 
C_x\left[
        \left( 
        \frac{1}{\textnormal {Vol\,} B_s}
        \right)^{\frac{1}{1+x}}
        \left\Vert\bar\lambda\right\Vert_{1+x} +1
\right]
$$
for some constant $C_x=C_x(B_s,\beta,x)>0$ which in fact is uniform in $s$, as all $B_s$ are congruent by translation. Setting $\displaystyle b_{x,\epsilon}:=\frac{C_x}{\epsilon}$ and using (43) we have
\begin{equation}        
        \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\leq
\frac{1}{\textnormal {Vol\,} B_s}\int_{B_s}\bar\lambda^{1+x}.
\end{equation}
In particular, one can choose at most $2\mathbf{\pi}\delta^+_\epsilon\in \mathbb{N}$ values $s_j\in I_\epsilon$ such that the corresponding $B_{s_j}$ are necessarily disjoint, and form their union 
\begin{displaymath}
        B\left( \epsilon \right):=\coprod\limits_{j=1}^{2\mathbf{\pi}\delta^+_\epsilon}
        B_{s_j}.
\end{displaymath}
Clearly $\textnormal {Vol\,} B(\epsilon)\geq \frac{1}{2}\left(2\mathbf{\pi}\delta^+_\epsilon\right)\textnormal {Vol\,} D$. Now, the statement about averages $(45)$ goes over to the disjoint union, hence
\begin{displaymath}
        \int_{\Sigma(\epsilon)}\bar\lambda^{1+x} 
        \geq \int_{B(\epsilon)}\bar\lambda^{1+x}
        \geq \textnormal {Vol\,} B(\epsilon) 
        \cdot 
        \left[
        \epsilon \left(L-b_{x,\epsilon}\right)
        \right]^{1+x}
\end{displaymath}
 which proves the \emph{Lemma}, with 
 $a_{x, \epsilon} := \left(\mathbf{\pi} \textnormal {Vol\,} D\right)\epsilon^{1+x}$.
\end{proof}

Suppose $\left.\mathcal{E}\right\vert_{D_z}$ is stable with Hermitian         Yang-Mills metric $\left.H_0\right\vert_{D_z}$; then there exists         a  constant $c_z>0$ such that 
