with $\gamma \left( 1\right) =H_{t}$ and $\gamma _{\ell }^{-1}.\dot{\gamma}
_{\ell }=\xi $. Using the first variation of curvature [\emph{Lemma 37}] we obtain $\frac{d}{d\ell }F_{\ell}=\bar{\partial}\partial _{\ell }\xi $, with $\partial_\ell:=\partial_{\gamma_{\ell}}$ and $F_\ell := F_{\gamma \left( \ell \right) }$.
Form [cf. (34)]
\begin{equation*}
m\left( \ell \right) := \int_{0}^{\ell }\int_{D_{z}}\Phi ^{\gamma
}\left( \ell \right) \wedge \omega =2\mathbf{i}\int_{0}^{\ell }\left(
\int_{D_{z}}\xi .F_{\ell}\wedge \omega \right) d\ell
\end{equation*}
so that $m\left( 1\right) =\mathcal{N}_{D_{z}}\left( H_{t}\right)$ and $
m\left( 0\right) =0$; differentiating along $\gamma $ we have
\begin{equation*}
m^{\prime }\left( \ell \right) =2\mathbf{i}\int_{D_{z}}\xi .F_{\ell}\wedge \omega .
\end{equation*}
The function $m\left( \ell \right) $ is in fact convex:
\begin{displaymath}
        m^{\prime \prime }\left( \ell \right) 
        =2\mathbf{i}\int_{D_{z}}\textnormal {tr\,}\xi .\left( \bar{\partial}_{\ell}
        \partial _{\ell }\xi \right) \wedge \omega 
        = 2\left\Vert \partial _{\ell }\xi \right\Vert ^{2}
        =\left\Vert \nabla_{\ell }\xi \right\Vert ^{2} \geq 0
\end{displaymath}
since $\xi $ is real, and so $\left\vert \partial _{\ell }\xi
\right\vert ^{2}=\left\vert \bar{\partial}_{\ell }\xi \right\vert ^{2}=\frac{
1}{2}\left\vert \nabla _{\ell }\xi \right\vert ^{2}$. Now, by the mean value theorem, there exists some $\ell \in\left[ 0,1 \right]$ such that
\begin{eqnarray*}
        \mathcal{N}_{D_{z}}\left( H_{t}\right)
        &=&m\left( 1\right) \;=\; m(0) + m^{\prime }\left( \ell \right) 
        \;\leq\; m^{\prime}(1)
        \;\leq\; 2\int_{D_{z}}\left\vert \xi.F_{1}\wedge \omega \right\vert \\
        &\leq & c_{1}\;L_t \;\Vert \widehat{\left.F_{1}\right\vert_{D_z}}\Vert
\end{eqnarray*}
using convexity and Cauchy-Schwarz, with $c_1:= 2\sup\limits_{\left\vert z \right\vert < \delta}\sqrt{\textnormal {Vol\,}(D_z)}$ and the notation $F_1=F_{H_t}$.
\end{proof}

For each $t>0$, the transversal supremum $\ell_t$ is bounded below over $I_t$ by the concave parabola $P_t(s-S_t):= L_t -\frac{\beta}{2}(s-S_t)(s-S_t+1)$, i.e.,
\begin{displaymath}
        \ell_t(s)\geq P_t(s), \quad \forall s\in I_t.
\end{displaymath}
\begin{proof}
Fix $t>0$, $\delta^+_t\geq\delta>0$ and set $J_t\left( \delta \right):= \left]S_{t}-1,S_{t}+\delta\right[ $ (I suppress henceforth the $t$ subscript everywhere, for clarity). The parabola takes the value $P(-1)=P(0)=L$ at the points $S-1$ and $S$, and its concavity $-P''_t=\beta$ is precisely the weak bound on $\Delta\bar\lambda$ [\emph{Lemma 50}], so we have $\Delta\left( \bar\lambda - P\right)\overset{w}{\leq}0$ on $\overline{J(\delta)}$ and  \emph{Lemma 49} gives
\begin{eqnarray*}
         \left.\left( \bar\lambda - P \right)\right\vert_{J(\delta)}
        &<& \max \left\{ 
        \sup\limits_{s=S-1} \left( \bar\lambda - P \right),  
        \sup\limits_{s=S+\delta}\left( \bar\lambda - P \right)\right\}\\
        \Rightarrow \quad0=\ell(S)-P(S) &<& \ell(S+\delta)-P(S+\delta),
        \quad \forall 0<\delta<\delta^+ 
\end{eqnarray*}
since by assumption $\ell(S-1)\leq L=P(-1)$. Hence $\ell\geq P,\quad \forall s\in I$.
\end{proof}

The Laplacian of $\bar\lambda$ admits a weak bound $\beta>0$:
\begin{displaymath}
        \Delta\bar\lambda_t \overset{w}{\leq} \beta, \qquad\forall t>0. 
\end{displaymath}
\begin{proof}
We know from [inf dets stab bdls...] that\begin{displaymath}
        \Delta\bar\lambda \overset{w}{\leq} 
        2 \left( \left\Vert \hat{F}_{H_t} \right\Vert_{H_t} 
        + \left\Vert \hat{F}_{H_0} \right\Vert_{H_0}\right),
\end{displaymath}
and the right-hand side is controlled by the time-uniform bound on $\hat{F}_{H_t}$ [\emph{Corollary 17}].
\end{proof}
